<template>
  <div class="stops-page">
    <v-snackbar v-model="snackbar" location="right top" :timeout="sb_timeout" :color="sb_type" elevation="10"><div class="snack"><v-icon :icon="sb_icon" size="22"/><div><strong>{{ sb_title }}</strong><small>{{ sb_message }}</small></div></div></v-snackbar>

    <header class="page-header">
      <div class="page-heading"><div class="page-icon"><v-icon size="21">mdi-map-marker-path</v-icon></div><div><h2>{{ routeTitle }}</h2><p>Organiza la secuencia y operación de las paradas</p></div></div>
      <div class="header-actions"><v-btn class="close-button" variant="text" prepend-icon="mdi-close" @click="$emit('close')">Cerrar</v-btn><v-btn class="add-button" prepend-icon="mdi-plus" elevation="0" @click="showAdd">Agregar parada</v-btn></div>
    </header>

    <v-container fluid class="page-content">
      <v-row class="summary-row">
        <v-col cols="12" sm="4"><div class="summary-card"><div class="summary-icon blue"><v-icon size="19">mdi-map-marker-multiple-outline</v-icon></div><div><b>{{ routeStops.length }}</b><span>Paradas configuradas</span></div></div></v-col>
        <v-col cols="12" sm="4"><div class="summary-card"><div class="summary-icon green"><v-icon size="19">mdi-account-arrow-up-outline</v-icon></div><div><b>{{ boardingStops }}</b><span>Permiten subida</span></div></div></v-col>
        <v-col cols="12" sm="4"><div class="summary-card"><div class="summary-icon amber"><v-icon size="19">mdi-account-arrow-down-outline</v-icon></div><div><b>{{ alightingStops }}</b><span>Permiten bajada</span></div></div></v-col>
      </v-row>

      <v-card class="table-panel" elevation="0">
        <div class="table-toolbar"><div><h3>Listado de paradas</h3><p>{{ countText }}</p></div><v-text-field v-model="search" class="search-field" density="compact" placeholder="Buscar parada..." prepend-inner-icon="mdi-magnify" variant="outlined" hide-details clearable/></div><v-divider/>
        <v-data-table v-model:items-per-page="itemsPerPage" v-model:page="page" v-model:sort-by="sortBy" :headers="headers" :items="routeStops" :search="search" :loading="loading" :items-per-page-options="[5,10,15,25]" items-per-page-text="Elementos por página" no-data-text="No hay paradas configuradas" loading-text="Cargando paradas..." class="stops-table">
          <template #loading><v-skeleton-loader type="table-row@5"/></template>
          <template #[`item.locationName`]="{ item }"><div class="stop-cell"><div class="stop-avatar"><v-img v-if="item.locationImage" :src="imageUrl(item.locationImage)" class="stop-photo" width="38" height="38" cover><template #error><div class="image-fallback"><v-icon size="18">mdi-map-marker-outline</v-icon></div></template></v-img><v-icon v-else size="18">mdi-map-marker-outline</v-icon></div><div><strong>{{ item.locationName || 'Sin nombre' }}</strong><small>{{ areaText(item) }}</small></div></div></template>
          <template #[`item.stop_order`]="{ item }"><span class="order-badge">{{ item.stop_order }}</span></template>
          <template #[`item.distance_km`]="{ item }"><span class="metric"><v-icon size="14">mdi-ruler</v-icon>{{ numberText(item.distance_km) }} km</span></template>
          <template #[`item.minutes_from_origin`]="{ item }"><span class="metric"><v-icon size="14">mdi-timer-outline</v-icon>{{ numberText(item.minutes_from_origin) }} min</span></template>
          <template #[`item.allows_boarding`]="{ item }"><span class="boolean-badge" :class="truthy(item.allows_boarding)?'yes':'no'"><v-icon size="13">{{ truthy(item.allows_boarding)?'mdi-check':'mdi-minus' }}</v-icon>{{ truthy(item.allows_boarding)?'Sí':'No' }}</span></template>
          <template #[`item.allows_alighting`]="{ item }"><span class="boolean-badge" :class="truthy(item.allows_alighting)?'yes':'no'"><v-icon size="13">{{ truthy(item.allows_alighting)?'mdi-check':'mdi-minus' }}</v-icon>{{ truthy(item.allows_alighting)?'Sí':'No' }}</span></template>
          <template #[`item.active`]="{ item }"><span class="status-badge" :class="truthy(item.active)?'active':'inactive'"><i/>{{ truthy(item.active)?'Activa':'Inactiva' }}</span></template>
          <template #[`item.actions`]="{ item }"><div class="actions"><v-tooltip text="Editar parada" location="top"><template #activator="{props}"><v-btn v-bind="props" icon="mdi-pencil-outline" variant="text" size="small" class="edit" @click="editItem(item)"/></template></v-tooltip><v-tooltip text="Eliminar parada" location="top"><template #activator="{props}"><v-btn v-bind="props" icon="mdi-trash-can-outline" variant="text" size="small" class="delete" @click="deleteItem(item)"/></template></v-tooltip></div></template>
        </v-data-table>
        <div class="table-note"><v-icon size="15">mdi-information-outline</v-icon>El orden determina la secuencia del recorrido desde su punto de origen.</div>
      </v-card>
    </v-container>

    <v-dialog v-model="dialog" max-width="720" persistent><v-form ref="form" v-model="valid" @submit.prevent="save"><v-card class="form-dialog" elevation="0">
      <div class="dialog-header"><div class="dialog-heading"><div class="dialog-icon"><v-icon size="20">mdi-map-marker-plus-outline</v-icon></div><div><h3>{{ formTitle }}</h3><p>{{ editedIndex===-1?'Incorpora una parada al recorrido':'Actualiza la configuración de la parada' }}</p></div></div><v-btn icon="mdi-close" variant="text" size="small" :disabled="loading" @click="close"/></div><v-divider/>
      <v-card-text class="dialog-body"><div class="section-label">Ubicación</div>
        <v-autocomplete v-model="editedItem.location_id" :items="locations" item-title="address" item-value="id" label="Parada" prepend-inner-icon="mdi-map-marker-outline" variant="outlined" density="comfortable" no-data-text="No hay ubicaciones disponibles" :rules="selectRules" class="location-select"><template #item="{props,item}"><v-list-item v-bind="props" class="location-option"><template #prepend><v-avatar size="36" rounded="lg" class="option-avatar"><v-img v-if="item.raw.image" :src="imageUrl(item.raw.image)" width="36" height="36" cover><template #error><div class="image-fallback"><v-icon size="18">mdi-map-marker-outline</v-icon></div></template></v-img><v-icon v-else size="18">mdi-map-marker-outline</v-icon></v-avatar></template><v-list-item-title>{{ item.raw.address }}</v-list-item-title><v-list-item-subtitle>{{ [item.raw.city,item.raw.country].filter(Boolean).join(', ') }}</v-list-item-subtitle></v-list-item></template></v-autocomplete>
        <div class="section-label spaced">Secuencia del recorrido</div><v-row dense><v-col cols="12" md="4"><v-text-field v-model="editedItem.stop_order" label="Orden" prepend-inner-icon="mdi-numeric" variant="outlined" density="comfortable" type="number" min="1" :rules="stopOrderRules"/></v-col><v-col cols="12" md="4"><v-text-field v-model="editedItem.distance_km" label="Distancia" suffix="km" prepend-inner-icon="mdi-ruler" variant="outlined" density="comfortable" type="number" step="0.1" min="0" :rules="numberRules"/></v-col><v-col cols="12" md="4"><v-text-field v-model="editedItem.minutes_from_origin" label="Tiempo desde origen" suffix="min" prepend-inner-icon="mdi-timer-outline" variant="outlined" density="comfortable" type="number" min="0" :rules="numberRules"/></v-col></v-row>
        <div class="section-label spaced">Operación en la parada</div><div class="switch-grid"><div class="switch-card"><div><strong>Permitir subida</strong><small>Los pasajeros pueden abordar.</small></div><v-switch v-model="editedItem.allows_boarding" color="success" hide-details inset/></div><div class="switch-card"><div><strong>Permitir bajada</strong><small>Los pasajeros pueden descender.</small></div><v-switch v-model="editedItem.allows_alighting" color="success" hide-details inset/></div><div class="switch-card"><div><strong>Parada activa</strong><small>Disponible para nuevos servicios.</small></div><v-switch v-model="editedItem.active" color="success" hide-details inset/></div></div>
      </v-card-text><v-divider/><v-card-actions class="dialog-actions"><v-btn variant="text" class="cancel" :disabled="loading" @click="close">Cancelar</v-btn><v-btn type="submit" class="save" elevation="0" :loading="loading" :disabled="!valid">{{ editedIndex===-1?'Crear parada':'Guardar cambios' }}</v-btn></v-card-actions>
    </v-card></v-form></v-dialog>

    <v-dialog v-model="dialogDelete" max-width="430" persistent><v-card class="delete-dialog" elevation="0"><div class="delete-icon"><v-icon size="27">mdi-trash-can-outline</v-icon></div><h3>Eliminar parada</h3><p>¿Deseas eliminar <strong>{{ editedItem.locationName || 'esta parada' }}</strong>? Esta acción no se puede deshacer.</p><div><v-btn variant="text" class="cancel" :disabled="loading" @click="closeDelete">Cancelar</v-btn><v-btn class="delete-confirm" elevation="0" :loading="loading" @click="deleteItemConfirm">Eliminar</v-btn></div></v-card></v-dialog>
  </div>
</template>

<script>
import { handleRequest } from "@/utils/api";
import LocalStorageService from "@/LocalStorageService";
export default{
  name:"RouteStop",emits:["close"],props:{route:{type:Object,required:true,default:()=>({})}},
  data:()=>({snackbar:false,sb_type:"",sb_message:"",sb_timeout:2000,sb_title:"",sb_icon:"",valid:false,loading:false,dialog:false,dialogDelete:false,routeStops:[],locations:[],search:"",page:1,itemsPerPage:10,sortBy:[],company_id:"",route_id:"",editedIndex:-1,
    headers:[{title:"Parada",key:"locationName",sortable:true,width:"27%"},{title:"Orden",key:"stop_order",sortable:true,width:"9%"},{title:"Distancia",key:"distance_km",sortable:true,width:"12%"},{title:"Minutos",key:"minutes_from_origin",sortable:true,width:"12%"},{title:"Subida",key:"allows_boarding",sortable:true,width:"10%"},{title:"Bajada",key:"allows_alighting",sortable:true,width:"10%"},{title:"Estado",key:"active",sortable:true,width:"11%"},{title:"",key:"actions",sortable:false,align:"end",width:"9%"}],
    editedItem:{id:"",company_id:"",route_id:"",location_id:"",locationName:"",stop_order:1,distance_km:0,minutes_from_origin:0,allows_boarding:true,allows_alighting:true,active:true},defaultItem:{id:"",company_id:"",route_id:"",location_id:"",locationName:"",stop_order:1,distance_km:0,minutes_from_origin:0,allows_boarding:true,allows_alighting:true,active:true},originalItem:{},selectRules:[v=>!!v||"Debes seleccionar una ubicación"],numberRules:[v=>v!==null&&v!==undefined&&v!==""||"El campo es requerido",v=>!Number.isNaN(Number(v))||"Debe ser un número válido",v=>Number(v)>=0||"No puede ser negativo"]}),
  computed:{formTitle(){return this.editedIndex===-1?"Agregar parada":"Editar parada"},routeTitle(){return this.route?.name?`Paradas de ${this.route.name}`:"Paradas de la ruta"},boardingStops(){return this.routeStops.filter(x=>this.truthy(x.allows_boarding)).length},alightingStops(){return this.routeStops.filter(x=>this.truthy(x.allows_alighting)).length},countText(){return this.routeStops.length===1?"1 parada configurada":`${this.routeStops.length} paradas configuradas`},stopOrderRules(){return[v=>v!==null&&v!==undefined&&v!==""||"El orden es requerido",v=>!Number.isNaN(Number(v))||"Debe ser un número válido",v=>Number(v)>=1||"Debe ser mayor o igual a 1",v=>!this.hasDuplicateStopOrder(v)||"Ya existe una parada con ese orden"]}},
  watch:{route:{deep:true,immediate:true,handler(value){this.company_id=value?.company_id||this.storage("business_id");this.route_id=value?.route_id||value?.id||"";if(this.route_id)this.initialize()}},search(){this.page=1}},
  methods:{storage(k){return String(LocalStorageService.getItem(k)??"").replace(/["']/g,"").trim()},truthy(v){return v===true||v===1||v==="1"},unwrap(item){return item?.raw??item??{}},clone(item){return{...item}},normalize(item={}){return{...item,company_id:item.company_id??this.company_id,route_id:item.route_id??this.route_id,stop_order:item.stop_order??1,distance_km:item.distance_km??0,minutes_from_origin:item.minutes_from_origin??0,allows_boarding:item.allows_boarding??true,allows_alighting:item.allows_alighting??true,active:item.active??true}},
    imageUrl(source){if(!source)return"";const image=String(source).trim();if(/^(https?:|data:|blob:)/i.test(image))return image;const base=String(this.$axios.defaults.baseURL||"");const clean=image.replace(/^\/+/,"");return clean.startsWith("images/")?`${base}${clean}`:`${base}images/${clean}`},areaText(item){return[item.locationCity,item.locationCountry].filter(Boolean).join(", ")||"Sin localidad"},numberText(v){const n=Number(v);return Number.isFinite(n)?n.toLocaleString("es-CL",{maximumFractionDigits:1}):"0"},getNextStopOrder(){const values=this.routeStops.map(x=>Number(x.stop_order)).filter(x=>Number.isFinite(x)&&x>0);return values.length?Math.max(...values)+1:1},hasDuplicateStopOrder(v){const n=Number(v);return Number.isFinite(n)&&this.routeStops.some(x=>!(this.editedIndex!==-1&&Number(x.id)===Number(this.editedItem.id))&&Number(x.stop_order)===n)},
    async loadLocations(){const r=await handleRequest({endpoint:"location",method:"GET"});const raw=r.success?(Array.isArray(r.data?.locations)?r.data.locations:Object.values(r.data?.locations||{})):[];this.locations=raw.map(x=>({...x,active:x.active??true}))},
    async initialize(){if(!this.route_id){this.routeStops=[];return}this.loading=true;try{const r=await handleRequest({endpoint:"route-stop-by-route",method:"POST",data:{route_id:this.route_id}});const raw=r.success?(Array.isArray(r.data?.routeStops)?r.data.routeStops:Object.values(r.data?.routeStops||{})):[];this.routeStops=raw.map(x=>this.normalize(x));if(!r.success)this.showAlert("warning",r.message||"No fue posible cargar las paradas.",3000)}catch(e){this.routeStops=[];this.showAlert("error","Ocurrió un error al cargar las paradas.",3000)}finally{this.loading=false}},
    reset(){this.editedItem=this.clone(this.defaultItem);this.originalItem=this.clone(this.defaultItem);this.editedIndex=-1;this.valid=false},async showAdd(){this.reset();try{await this.loadLocations();this.editedItem.company_id=this.company_id;this.editedItem.route_id=this.route_id;this.editedItem.stop_order=this.getNextStopOrder();this.dialog=true;this.$nextTick(()=>this.$refs.form?.resetValidation())}catch(e){this.showAlert("error","No fue posible cargar las ubicaciones.",3000)}},close(){if(this.loading)return;this.dialog=false;this.$nextTick(()=>{this.reset();this.$refs.form?.resetValidation()})},
    async save(){const validation=await this.$refs.form?.validate();if(!validation?.valid)return;if(this.hasDuplicateStopOrder(this.editedItem.stop_order)){this.showAlert("warning","Ya existe una parada con ese orden.",3000);return}const creating=this.editedIndex===-1;const payload={company_id:this.company_id,route_id:this.route_id,location_id:this.editedItem.location_id,stop_order:Number(this.editedItem.stop_order),distance_km:Number(this.editedItem.distance_km),minutes_from_origin:Number(this.editedItem.minutes_from_origin),allows_boarding:!!this.editedItem.allows_boarding,allows_alighting:!!this.editedItem.allows_alighting,active:!!this.editedItem.active};if(!creating)payload.id=this.editedItem.id;this.loading=true;try{const r=await handleRequest({endpoint:"route-stop",method:creating?"POST":"PUT",data:payload});if(r.success){this.dialog=false;this.showAlert("success",r.message||"Parada guardada correctamente.",3000);await this.initialize();this.reset()}else this.showAlert("warning",r.message||"No fue posible guardar la parada.",3000)}catch(e){this.showAlert("error","Ocurrió un error al guardar la parada.",3000)}finally{this.loading=false}},
    async editItem(item){const stop=this.normalize(this.unwrap(item));this.editedIndex=this.routeStops.findIndex(x=>String(x.id)===String(stop.id));this.originalItem=this.clone(stop);this.editedItem=this.clone(stop);try{await this.loadLocations();if(stop.location_id&&!this.locations.some(x=>String(x.id)===String(stop.location_id)))this.locations.push({id:stop.location_id,address:stop.locationName,image:stop.locationImage,city:stop.locationCity,country:stop.locationCountry});this.dialog=true;this.$nextTick(()=>this.$refs.form?.resetValidation())}catch(e){this.showAlert("error","No fue posible cargar las ubicaciones.",3000)}},deleteItem(item){const stop=this.unwrap(item);this.editedItem={...this.defaultItem,...stop};this.dialogDelete=true},closeDelete(){if(!this.loading){this.dialogDelete=false;this.reset()}},
    async deleteItemConfirm(){this.loading=true;try{const r=await handleRequest({endpoint:"route-stop-destroy",method:"POST",data:{id:this.editedItem.id}});if(r.success){this.dialogDelete=false;this.showAlert("success",r.message||"Parada eliminada correctamente.",3000);await this.initialize();this.reset()}else this.showAlert("warning",r.message||"No fue posible eliminar la parada.",3000)}catch(e){this.showAlert("error","Ocurrió un error al eliminar la parada.",3000)}finally{this.loading=false}},showAlert(type,message,timeout=3000){const cfg={success:["Éxito","mdi-check-circle"],warning:["Advertencia","mdi-alert-circle"],error:["Error","mdi-close-circle"]}[type]||["Información","mdi-information"];this.sb_type=type;this.sb_title=cfg[0];this.sb_icon=cfg[1];this.sb_message=message;this.sb_timeout=timeout;this.snackbar=true}
  }
}
</script>

<style scoped>
.stops-page{min-height:100vh;color:#1e293b;background:#f6f8fb}.page-header{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:70px;padding:12px 24px;background:#fff;border-bottom:1px solid #e8edf5}.page-heading,.dialog-heading,.header-actions{display:flex;align-items:center;gap:11px}.page-icon,.dialog-icon{display:grid;flex:0 0 38px;width:38px;height:38px;place-items:center;color:#fff;background:linear-gradient(135deg,#0e1f46,#2454d6);border-radius:10px;box-shadow:0 5px 12px rgba(36,84,214,.17)}h2,h3,p{margin:0}.page-heading h2{color:#0f172a;font-size:18px;font-weight:850}.page-heading p,.dialog-heading p{margin-top:3px;color:#64748b;font-size:11.5px;font-weight:650}.add-button,.save{min-height:40px;color:#fff!important;background:linear-gradient(100deg,#2454d6,#3266e4)!important;border-radius:9px!important;font-size:12.5px;font-weight:800;text-transform:none}.close-button{color:#475569!important;font-size:12px;font-weight:750;text-transform:none}.page-content{padding:18px 24px 28px}.summary-row{margin-bottom:4px}.summary-card{display:flex;align-items:center;gap:11px;min-height:72px;padding:13px 15px;background:#fff;border:1px solid #e8edf5;border-radius:12px}.summary-icon{display:grid;width:36px;height:36px;place-items:center;border-radius:9px}.summary-icon.blue{color:#2454d6;background:#eef3ff}.summary-icon.green{color:#16875a;background:#eaf8f1}.summary-icon.amber{color:#b86a08;background:#fff6e6}.summary-card b{display:block;color:#0f172a;font-size:20px;font-weight:900;line-height:1}.summary-card span{display:block;margin-top:4px;color:#526176;font-size:11px;font-weight:700}.table-panel{overflow:hidden;background:#fff;border:1px solid #e8edf5;border-radius:13px!important}.table-toolbar{display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:69px;padding:12px 17px}.table-toolbar h3{color:#0f172a;font-size:15px;font-weight:850}.table-toolbar p{margin-top:3px;color:#64748b;font-size:11px;font-weight:650}.search-field{flex:0 1 320px}.search-field :deep(.v-field){border-radius:9px;font-size:12px}.stops-table :deep(thead th){height:40px!important;color:#334155!important;font-size:11px!important;font-weight:850!important;text-transform:uppercase;background:#f8fafc!important}.stops-table :deep(tbody td){height:62px!important;color:#1e293b;font-size:12.5px;font-weight:650;border-bottom:1px solid #eef2f6!important}.stop-cell{display:flex;align-items:center;gap:10px;min-width:0}.stop-avatar{display:grid;flex:0 0 38px;width:38px;height:38px;overflow:hidden;place-items:center;color:#2454d6;background:#eef3ff;border:1px solid #dce6ff;border-radius:9px}.stop-photo{width:100%!important;height:100%!important}.image-fallback{display:grid;width:100%;height:100%;place-items:center;color:#2454d6}.stop-cell strong{display:block;max-width:260px;overflow:hidden;color:#0f172a;font-size:13px;font-weight:850;text-overflow:ellipsis;white-space:nowrap}.stop-cell small{display:block;margin-top:2px;color:#64748b;font-size:10.5px;font-weight:650}.order-badge{display:grid;width:27px;height:27px;place-items:center;color:#2454d6;background:#eef3ff;border-radius:8px;font-weight:850}.metric{display:inline-flex;align-items:center;gap:5px;color:#334155;white-space:nowrap;font-size:11.5px;font-weight:750}.boolean-badge,.status-badge{display:inline-flex;align-items:center;gap:4px;padding:4px 7px;border-radius:7px;font-size:11px;font-weight:800}.yes,.active{color:#116b49;background:#eaf8f1}.no,.inactive{color:#64748b;background:#f1f5f9}.status-badge i{width:6px;height:6px;background:currentColor;border-radius:50%}.actions{display:flex;justify-content:flex-end;gap:2px}.edit{color:#2454d6!important}.delete{color:#dc2626!important}.table-note{display:flex;align-items:center;gap:6px;min-height:42px;padding:9px 16px;color:#64748b;font-size:10.5px;font-weight:650;border-top:1px solid #edf1f5}.form-dialog,.delete-dialog{overflow:hidden;color:#1e293b;background:#fff;border:1px solid #dfe6ef;border-radius:14px!important;box-shadow:0 22px 60px rgba(15,23,42,.2)!important}.dialog-header{display:flex;align-items:center;justify-content:space-between;padding:17px 20px}.dialog-heading h3{color:#0f172a;font-size:16px;font-weight:850}.dialog-body{max-height:70vh;padding:21px 22px 16px!important;overflow-y:auto}.section-label{margin-bottom:13px;color:#475569;font-size:10.5px;font-weight:850;letter-spacing:.065em;text-transform:uppercase}.section-label.spaced{margin-top:7px}.dialog-body :deep(.v-field){border-radius:9px}.switch-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.switch-card{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 11px;background:#f8fafc;border:1px solid #e8edf5;border-radius:10px}.switch-card strong{display:block;color:#334155;font-size:11.5px;font-weight:800}.switch-card small{display:block;margin-top:3px;color:#64748b;font-size:9.5px}.dialog-actions{justify-content:flex-end;gap:9px;padding:14px 20px!important}.cancel{min-width:94px;min-height:39px;color:#475569!important;font-size:12.5px;font-weight:750;text-transform:none}.save{min-width:150px}.delete-dialog{padding:29px 27px 24px;text-align:center}.delete-icon{display:grid;width:56px;height:56px;margin:0 auto 16px;place-items:center;color:#dc2626;background:#fff1f2;border-radius:15px}.delete-dialog h3{color:#0f172a;font-size:18px;font-weight:850}.delete-dialog p{margin:10px auto 22px;color:#64748b;font-size:12.5px;line-height:1.55}.delete-confirm{min-width:112px;min-height:40px;color:#fff!important;background:#dc2626!important;border-radius:9px!important;font-weight:800;text-transform:none}.snack{display:flex;align-items:center;gap:10px}.snack strong,.snack small{display:block}.snack small{margin-top:2px}
